function splitLines(text){
  return String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
}
function buildStandup(f){
  f=f||{};
  var yest=splitLines(f.yesterday), today=splitLines(f.today), block=splitLines(f.blockers);
  var who=String(f.team||'').trim();
  var lines=['# 每日站会'+(who?(' · '+who):''), '', '## 昨日完成'];
  yest.forEach(function(x){ lines.push('- '+x); }); if(!yest.length) lines.push('- （无）');
  lines.push('','## 今日计划');
  today.forEach(function(x){ lines.push('- '+x); }); if(!today.length) lines.push('- （无）');
  lines.push('','## 障碍 / 风险');
  block.forEach(function(x){ lines.push('- ⚠ '+x); }); if(!block.length) lines.push('- 无');
  return {markdown:lines.join('\n'), yest:yest.length, today:today.length, blockers:block.length};
}
var EXPORTS={splitLines:splitLines, buildStandup:buildStandup};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StandupForgePure = EXPORTS; }
